        if (base64Audio) {
            return base64Audio;
        } else {
             throw new Error("API tidak mengembalikan data audio.");
        }
    } catch (error) {
        console.error("Gemini audio generation failed:", error);
        throw new Error("Gagal menghasilkan audio dari Gemini.");
    }
};

import React, { useState, useEffect } from 'react';
import type { Scene } from '../types';
import { generateImageForScene, generateAudioForScene } from '../services/geminiService';
import { decode, decodeAudioData, audioBufferToUrl } from '../utils/audioUtils';

interface SceneCardProps {
  scene: Scene;
  index: number;
  voice: string;
  style: string;
  nicheId: string;
}

let audioContext: AudioContext | null = null;
const getAudioContext = () => {
  if (!audioContext) {
    // FIX: Add `(window as any)` to support `webkitAudioContext` in TypeScript
    audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  }
  return audioContext;
};

const CopyIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
  </svg>
);

const CheckIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
  </svg>
);

const DownloadIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
  </svg>
);

const SceneCard: React.FC<SceneCardProps> = ({ scene, index, voice, style, nicheId }) => {
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [imageError, setImageError] = useState<string | null>(null);

  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [generatedAudioUrl, setGeneratedAudioUrl] = useState<string | null>(null);
  const [audioError, setAudioError] = useState<string | null>(null);

  const [visualPrompt, setVisualPrompt] = useState(scene.visual_prompt);
  const [voiceOverScript, setVoiceOverScript] = useState(scene.voice_over_script);

  const [copiedPrompt, setCopiedPrompt] = useState(false);
  const [copiedScript, setCopiedScript] = useState(false);

  useEffect(() => {
    setVisualPrompt(scene.visual_prompt);
    setVoiceOverScript(scene.voice_over_script);
  }, [scene]);

  const handleCopy = (text: string, type: 'prompt' | 'script') => {
    navigator.clipboard.writeText(text);
    if (type === 'prompt') {
        setCopiedPrompt(true);
        setTimeout(() => setCopiedPrompt(false), 2000);
    } else {
        setCopiedScript(true);
        setTimeout(() => setCopiedScript(false), 2000);
    }
  };

  const handleGenerateImage = async () => {
    setIsGeneratingImage(true);
    setGeneratedImage(null);
    setImageError(null);
    try {
      let finalPrompt = visualPrompt;
      if (nicheId === 'animasi-anak') {
          finalPrompt += ", 3D Disney Pixar Animation style, unreal engine 5 render, cute, vibrant colors, high quality, consistent character features";
      }
      const fullPrompt = `${finalPrompt}, aspect ratio 16:9`;
      const base64Image = await generateImageForScene(fullPrompt);
      setGeneratedImage(`data:image/jpeg;base64,${base64Image}`);
    } catch (err) {
      setImageError(err instanceof Error ? err.message : "Gagal menghasilkan gambar.");
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleGenerateAudio = async () => {
    setIsGeneratingAudio(true);
    setGeneratedAudioUrl(null);
    setAudioError(null);
    try {
      const base64Audio = await generateAudioForScene(voiceOverScript, voice, style);
      const audioBytes = decode(base64Audio);
      const ctx = getAudioContext();
      const audioBuffer = await decodeAudioData(audioBytes, ctx, 24000, 1);
      const url = audioBufferToUrl(audioBuffer);
      setGeneratedAudioUrl(url);
    } catch (err) {
      setAudioError(err instanceof Error ? err.message : "Gagal menghasilkan audio.");
    } finally {
      setIsGeneratingAudio(false);
    }
  };

  return (
    <div className="bg-slate-800 border border-slate-700 rounded-lg shadow-lg overflow-hidden animate-fade-in" style={{ animationDelay: `${index * 150}ms` }}>
      <div className="p-6 bg-slate-800/50">
        <h4 className="text-sm font-bold text-purple-400">ADEGAN {scene.scene_number}</h4>
        <p className="text-xl font-semibold text-slate-100 mt-1">{scene.scene_title}</p>
      </div>

      <div className="p-6 grid md:grid-cols-2 gap-6 border-t border-slate-700">
        {/* Visuals Section */}
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <h5 className="font-semibold text-slate-300">Visual Footage</h5>
             <button 
                onClick={() => handleCopy(visualPrompt, 'prompt')} 
                className="text-slate-400 hover:text-white transition-colors p-1" 
                title="Salin Prompt"
             >
                {copiedPrompt ? <CheckIcon /> : <CopyIcon />}
             </button>
          </div>
          <textarea
             value={visualPrompt}
             onChange={(e) => setVisualPrompt(e.target.value)}
             className="w-full p-4 bg-slate-900/70 rounded-md border border-slate-600 text-slate-400 text-sm italic min-h-[120px] focus:ring-2 focus:ring-blue-500 outline-none resize-y"
          />
          <button onClick={handleGenerateImage} disabled={isGeneratingImage} className="w-full text-sm py-2 px-4 rounded-md font-semibold text-white bg-blue-600 hover:bg-blue-700 disabled:bg-slate-600 transition-colors">
            {isGeneratingImage ? 'Membuat Gambar...' : 'Hasilkan Gambar'}
          </button>
          <div className="mt-4 aspect-video bg-slate-900 rounded-md flex items-center justify-center border border-slate-700 relative">
            {isGeneratingImage && <div className="w-8 h-8 border-2 border-blue-400 border-t-transparent rounded-full animate-spin"></div>}
            {imageError && <p className="text-xs text-red-400 p-2">{imageError}</p>}
            {generatedImage && (
              <>
                <img src={generatedImage} alt={scene.scene_title} className="w-full h-full object-cover"/>
                <a
                  href={generatedImage}
                  download={`scene_${scene.scene_number}_${scene.scene_title.replace(/\s+/g, '_')}.jpg`}
                  className="absolute top-2 right-2 p-2 bg-slate-900/60 rounded-full text-white hover:bg-slate-700/80 transition-colors"
                  aria-label="Unduh gambar"
                  title="Unduh gambar"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                </a>
              </>
            )}
            {!isGeneratingImage && !generatedImage && !imageError && <p className="text-slate-500 text-sm">Pratinjau Gambar</p>}
          </div>
        </div>

        {/* Narration Section */}
        <div className="space-y-3 flex flex-col">
          <div className="flex justify-between items-center">
             <h5 className="font-semibold text-slate-300">Narasi Voice-Over</h5>
             <button 
                onClick={() => handleCopy(voiceOverScript, 'script')} 
                className="text-slate-400 hover:text-white transition-colors p-1" 
                title="Salin Script"
             >
                {copiedScript ? <CheckIcon /> : <CopyIcon />}
             </button>
          </div>

          <textarea
            value={voiceOverScript}
            onChange={(e) => setVoiceOverScript(e.target.value)}
            className="w-full p-4 bg-slate-900/70 rounded-md border border-slate-600 text-slate-300 min-h-[120px] focus:ring-2 focus:ring-green-500 outline-none resize-y flex-grow"
          />

          <button onClick={handleGenerateAudio} disabled={isGeneratingAudio} className="w-full text-sm mt-auto py-2 px-4 rounded-md font-semibold text-white bg-green-600 hover:bg-green-700 disabled:bg-slate-600 transition-colors">
            {isGeneratingAudio ? 'Membuat Audio...' : 'Hasilkan Audio'}
          </button>

          <div className="mt-4 flex flex-col justify-end min-h-[3rem]">
             {isGeneratingAudio && <div className="text-center text-sm text-slate-400">Memproses audio...</div>}
             {audioError && <p className="text-xs text-red-400">{audioError}</p>}
             {generatedAudioUrl && (
                <div className="flex items-center gap-2 w-full">
                    <audio controls src={generatedAudioUrl} className="w-full h-10 flex-grow rounded-md"></audio>
                    <a
                        href={generatedAudioUrl}
                        download={`scene_${scene.scene_number}_audio.wav`}
                        className="p-2 bg-slate-700 hover:bg-slate-600 rounded-full text-slate-200 hover:text-white transition-colors flex-shrink-0"
                        title="Unduh Audio"
                        aria-label="Unduh Audio"
                    >
                        <DownloadIcon />
                    </a>
                </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SceneCard;

