export const generateImageForScene = async (prompt: string): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API Key belum terdeteksi.");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: prompt }],
            },
            config: {
                responseModalities: [Modality.IMAGE],
            },
        });

        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
                return part.inlineData.data; 
            }
        }
        throw new Error("API tidak mengembalikan gambar.");
    } catch (error) {
        console.error("Gemini image generation failed:", error);
        throw new Error("Gagal menghasilkan gambar dari Gemini.");
    }
};

export const generateAudioForScene = async (script: string, voiceName: string, style: string): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API Key belum terdeteksi.");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Say in a ${style || 'neutral'} tone: ${script}`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: prompt }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: voiceName },
                    },
                },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
            return base64Audio;
        } else {
             throw new Error("API tidak mengembalikan data audio.");
        }
    } catch (error) {
        console.error("Gemini audio generation failed:", error);
        throw new Error("Gagal menghasilkan audio dari Gemini.");
    }
};

import React, { useState, useCallback, useEffect } from 'react';
import type { Idea, Niche, Language } from './types';
import { generateContentIdeas } from './services/geminiService';
import Header from './components/Header';
import InputForm from './components/InputForm';
import IdeaCard from './components/IdeaCard';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorMessage from './components/ErrorMessage';
import ScriptView from './components/ScriptView';
import PasswordScreen from './components/PasswordScreen';
import NicheSelector from './components/NicheSelector';
import { niches } from './nicheData';

// Declare window interface for aistudio to avoid TS errors
declare global {
  interface Window {
    aistudio?: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const WelcomeMessage: React.FC = () => (
  <div className="text-center p-8 bg-slate-800/50 rounded-lg border border-slate-700 animate-fade-in">
    <h2 className="text-2xl font-bold text-slate-100 mb-2">Selamat Datang di CineMind AI!</h2>
    <p className="text-slate-400">
      Masukkan tema video Anda di atas dan biarkan AI kami merancang 3 angle cerita yang unik dan menarik, khusus untuk niche channel YouTube Anda.
    </p>
  </div>
);

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [hasApiKey, setHasApiKey] = useState(false);
  const [currentView, setCurrentView] = useState<'ideas' | 'script'>('ideas');
  const [selectedNiche, setSelectedNiche] = useState<Niche | null>(null);
  const [selectedIdea, setSelectedIdea] = useState<Idea | null>(null);
  const [selectedLanguage, setSelectedLanguage] = useState<Language>('id');
  const [ideas, setIdeas] = useState<Idea[]>([]);
  const [isLoadingIdeas, setIsLoadingIdeas] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [script, setScript] = useState([]);

  // Check for API key on mount
  useEffect(() => {
    const checkApiKey = async () => {
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        // Fallback for environments where aistudio wrapper isn't present (e.g., local dev)
        // In production AI Studio, this should be defined.
        setHasApiKey(true);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectKey = async () => {
      if (window.aistudio && window.aistudio.openSelectKey) {
          await window.aistudio.openSelectKey();
          setHasApiKey(true);
      }
  };

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleNicheSelect = (niche: Niche) => {
    setSelectedNiche(niche);
    setError(null);
    setIdeas([]);
  };

  const handleBackToNiches = () => {
    setSelectedNiche(null);
  };

  const handleGenerateIdeas = useCallback(async (theme: string, language: Language) => {
    if (!selectedNiche) {
        setError("Silakan pilih niche terlebih dahulu.");
        return;
    }
    if (!theme.trim()) {
      setError("Tema tidak boleh kosong.");
      return;
    }

    setIsLoadingIdeas(true);
    setError(null);
    setIdeas([]);
    setSelectedLanguage(language);

    try {
      const generatedIdeas = await generateContentIdeas(theme, selectedNiche.id, language);
      setIdeas(generatedIdeas);
    } catch (err) {
      console.error(err);
      const errorMessage = err instanceof Error ? err.message : "Terjadi kesalahan yang tidak diketahui.";

      // If error suggests permission issues, prompt to re-select key
      if (errorMessage.toLowerCase().includes("permission") || errorMessage.toLowerCase().includes("api key")) {
          setHasApiKey(false);
          setError("Izin ditolak atau API Key tidak valid. Silakan hubungkan ulang API Key Anda.");
      } else {
          setError(errorMessage);
      }
    } finally {
      setIsLoadingIdeas(false);
    }
  }, [selectedNiche]);

  const handleSelectIdea = (idea: Idea) => {
    setSelectedIdea(idea);
    setCurrentView('script');
  };

  const handleBackToIdeas = () => {
    setSelectedIdea(null);
    setScript([]); // Clear script when going back
    setCurrentView('ideas');
  };

  const renderContent = () => {
    if (currentView === 'script' && selectedIdea && selectedNiche) {
        return <ScriptView selectedIdea={selectedIdea} selectedNiche={selectedNiche} selectedLanguage={selectedLanguage} onBack={handleBackToIdeas} />;
    }

    if (!selectedNiche) {
        return <NicheSelector niches={niches} onSelect={handleNicheSelect} />;
    }

    return (
      <div className="animate-fade-in">
        <InputForm 
            onGenerate={handleGenerateIdeas} 
            isLoading={isLoadingIdeas}
            selectedNicheName={selectedNiche.name}
            selectedNicheId={selectedNiche.id}
            onBackToNiches={handleBackToNiches}
        />

        <div className="mt-10">
          {isLoadingIdeas && <LoadingSpinner />}
          {error && <ErrorMessage message={error} />}

          {!isLoadingIdeas && !error && ideas.length === 0 && <WelcomeMessage />}

          {!isLoadingIdeas && !error && ideas.length > 0 && (
            <div className="space-y-6">
              {ideas.map((idea, index) => (
                <IdeaCard key={index} idea={idea} index={index} onSelect={handleSelectIdea} />
              ))}
            </div>
          )}
        </div>
      </div>
    );
  };


  if (!isAuthenticated) {
    return <PasswordScreen onLoginSuccess={handleLoginSuccess} />;
  }

  // API Key Gate - displayed after authentication if key is missing/invalid
  if (!hasApiKey) {
    return (
      <div className="min-h-screen bg-slate-900 text-slate-200 font-sans flex items-center justify-center p-4">
           <div className="bg-slate-800 p-8 rounded-lg border border-slate-700 text-center max-w-md w-full shadow-2xl animate-fade-in">
              <h2 className="text-3xl font-bold mb-3 text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-blue-500">
                Setup API Key
              </h2>
              <p className="text-slate-400 mb-8">
                  Untuk menggunakan CineMind AI, Anda perlu menghubungkan API Key Google Gemini yang valid.
              </p>
              <button 
                  onClick={handleSelectKey}
                  className="w-full py-4 px-6 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold text-lg shadow-lg hover:shadow-blue-500/20 transition-all duration-200 transform hover:-translate-y-1"
              >
                  Pilih / Hubungkan API Key
              </button>
              <div className="mt-6 pt-6 border-t border-slate-700">
                 <p className="text-xs text-slate-500">
                    Belum punya key? <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:text-blue-300 hover:underline">Lihat info billing Google</a>
                 </p>
              </div>
           </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 font-sans">
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <Header />
        <main>
            {renderContent()}
        </main>

        <footer className="text-center mt-12 text-slate-500 text-sm">
          <p>Powered by Ipta Apipah - Mediacuan.com</p>
        </footer>
      </div>
    </div>
  );
}

