    if (!process.env.API_KEY) {
        throw new Error("API Key belum terdeteksi. Silakan hubungkan API Key Anda.");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Say in a ${style || 'neutral'} tone: ${script}`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: prompt }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: voiceName },
                    },
                },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
            return base64Audio;
        } else {
             throw new Error("API tidak mengembalikan data audio.");
        }
    } catch (error) {
        console.error("Gemini audio generation failed:", error);
        throw new Error("Gagal menghasilkan audio.");
    }
};

import React, { useState, useEffect } from 'react';
import type { Idea, Scene, PreProductionAssets, Niche, Language } from '../types';
import { generateScript, generatePreProductionAssets, generateImageForScene } from '../services/geminiService';
import SceneCard from './SceneCard';
import LoadingSpinner from './LoadingSpinner';
import ErrorMessage from './ErrorMessage';

interface ScriptViewProps {
  selectedIdea: Idea;
  selectedNiche: Niche;
  selectedLanguage: Language;
  onBack: () => void;
}

const voiceOptions = [
  { name: 'Pria (Berat & Dramatis) - Fenrir', value: 'Fenrir' },
  { name: 'Pria (Jelas & Enerjik) - Puck', value: 'Puck' },
  { name: 'Pria (Tenang & Informatif) - Charon', value: 'Charon' },
  { name: 'Pria (Formal & Otoritatif) - Zephyr', value: 'Zephyr' },
  { name: 'Wanita (Default) - Kore', value: 'Kore' },
];

const ScriptView: React.FC<ScriptViewProps> = ({ selectedIdea, selectedNiche, selectedLanguage, onBack }) => {
  const [duration, setDuration] = useState('10');
  const [script, setScript] = useState<Scene[] | null>(null);
  const [isLoadingScript, setIsLoadingScript] = useState(false);
  const [scriptError, setScriptError] = useState<string | null>(null);

  const [assets, setAssets] = useState<PreProductionAssets | null>(null);
  const [editableThumbnailPrompt, setEditableThumbnailPrompt] = useState('');
  const [isLoadingAssets, setIsLoadingAssets] = useState(true);
  const [assetsError, setAssetsError] = useState<string | null>(null);

  const [thumbnailImage, setThumbnailImage] = useState<string | null>(null);
  const [isGeneratingThumbnail, setIsGeneratingThumbnail] = useState(false);
  const [thumbnailError, setThumbnailError] = useState<string | null>(null);

  const [globalVoice, setGlobalVoice] = useState(voiceOptions[0].value);
  const [globalStyle, setGlobalStyle] = useState('');

  const [copiedDescription, setCopiedDescription] = useState(false);
  const [copiedHashtags, setCopiedHashtags] = useState(false);

  useEffect(() => {
    const fetchAssets = async () => {
      setIsLoadingAssets(true);
      setAssetsError(null);
      try {
        const generatedAssets = await generatePreProductionAssets(selectedIdea, selectedNiche.id, selectedLanguage);
        setAssets(generatedAssets);
        setEditableThumbnailPrompt(generatedAssets.thumbnail_prompt);
      } catch (err) {
        setAssetsError(err instanceof Error ? err.message : "Gagal memuat aset pra-produksi.");
      } finally {
        setIsLoadingAssets(false);
      }
    };
    fetchAssets();
  }, [selectedIdea, selectedNiche, selectedLanguage]);

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoadingScript(true);
    setScriptError(null);
    setScript(null);
    try {
      const generatedScript = await generateScript(selectedIdea, `${duration} menit`, selectedNiche.id, selectedLanguage);
      setScript(generatedScript);
    } catch (err) {
      setScriptError(err instanceof Error ? err.message : "Gagal membuat naskah.");
    } finally {
      setIsLoadingScript(false);
    }
  };

  const handleGenerateThumbnail = async () => {
    if (!editableThumbnailPrompt) return;
    setIsGeneratingThumbnail(true);
    setThumbnailImage(null);
    setThumbnailError(null);
    try {
        let prompt = editableThumbnailPrompt;
        if (selectedNiche.id === 'animasi-anak' && !prompt.includes('3D Disney Pixar')) {
             prompt += ", 3D Disney Pixar Animation style, unreal engine 5 render, cute, vibrant colors, high quality, consistent character features";
        }
        const fullPrompt = `${prompt}, aspect ratio 16:9`;
        const base64Image = await generateImageForScene(fullPrompt);
        setThumbnailImage(`data:image/jpeg;base64,${base64Image}`);
    } catch (err) {
        setThumbnailError(err instanceof Error ? err.message : "Gagal menghasilkan thumbnail.");
    } finally {
        setIsGeneratingThumbnail(false);
    }
  };

  const handleCopyText = (text: string, type: 'desc' | 'tag') => {
    navigator.clipboard.writeText(text);
    if (type === 'desc') {
        setCopiedDescription(true);
        setTimeout(() => setCopiedDescription(false), 2000);
    } else {
        setCopiedHashtags(true);
        setTimeout(() => setCopiedHashtags(false), 2000);
    }
  };

  return (
    <div className="animate-fade-in">
      <button 
        onClick={onBack} 
        className="mb-6 flex items-center px-4 py-2 bg-slate-700 hover:bg-slate-600 rounded-md text-slate-300 transition-colors"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
          <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
        </svg>
        Kembali ke Ide
      </button>

      <div className="bg-slate-800/50 p-6 rounded-lg border border-slate-700 mb-8">
        <p className="text-sm text-blue-400 font-semibold">IDE TERPILIH</p>
        <h2 className="text-2xl font-bold text-slate-100 mt-1">{selectedIdea.title}</h2>
        <p className="text-slate-400 mt-2">{selectedIdea.angle}</p>
      </div>

      {isLoadingAssets && <LoadingSpinner />}
      {assetsError && <ErrorMessage message={assetsError} />}
      {assets && (
        <div className="bg-slate-800/50 p-6 rounded-lg border border-slate-700 mb-8 animate-fade-in">
            <h3 className="text-xl font-bold text-slate-100 mb-4 border-b border-slate-700 pb-2">Aset Pra-Produksi</h3>
            <div className="grid md:grid-cols-2 gap-8">
                {/* Left Column: Titles, Description, Hashtags */}
                <div className="space-y-6">
                    <div>
                        <h4 className="font-semibold text-purple-400 mb-2 flex items-center">
                          <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"></path></svg>
                          Alternatif Judul
                        </h4>
                        <ul className="list-disc list-inside space-y-1 text-slate-300 bg-slate-900/40 p-3 rounded-md border border-slate-700/50">
                            {assets.titles.map((title, i) => <li key={i}>{title}</li>)}
                        </ul>
                    </div>

                    <div>
                        <div className="flex justify-between items-center mb-2">
                           <h4 className="font-semibold text-purple-400 flex items-center">
                             <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h7"></path></svg>
                             Deskripsi Video
                           </h4>
                           <button 
                             onClick={() => handleCopyText(assets.description, 'desc')}
                             className="text-xs bg-slate-700 hover:bg-slate-600 text-slate-300 px-2 py-1 rounded transition-colors"
                           >
                             {copiedDescription ? 'Tersalin!' : 'Salin'}
                           </button>
                        </div>
                        <div className="p-3 bg-slate-900/70 rounded-md border border-slate-600 max-h-40 overflow-y-auto text-sm text-slate-300 leading-relaxed">
                            {assets.description}
                        </div>
                    </div>

                    <div>
                        <div className="flex justify-between items-center mb-2">
                           <h4 className="font-semibold text-purple-400 flex items-center">
                             <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 20l4-16m2 16l4-16M6 9h14M4 15h14"></path></svg>
                             Hashtag
                           </h4>
                           <button 
                             onClick={() => handleCopyText(assets.hashtags.join(' '), 'tag')}
                             className="text-xs bg-slate-700 hover:bg-slate-600 text-slate-300 px-2 py-1 rounded transition-colors"
                           >
                             {copiedHashtags ? 'Tersalin!' : 'Salin'}
                           </button>
                        </div>
                        <div className="p-2 bg-slate-900/70 rounded-md border border-slate-600 text-sm text-blue-400 font-mono">
                            {assets.hashtags.join(' ')}
                        </div>
                    </div>
                </div>

                {/* Right Column: Thumbnail Controls */}
                <div className="space-y-4">
                     <div>
                        <h4 className="font-semibold text-purple-400 mb-2">Teks Thumbnail</h4>
                        <p className="p-3 bg-slate-900/70 rounded-md border border-slate-600 text-slate-200 font-bold text-lg text-center">"{assets.thumbnail_text}"</p>
                    </div>

                    <div className="space-y-3">
                        <h4 className="font-semibold text-purple-400 flex items-center">
                          <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                          Prompt Thumbnail (Bisa diedit)
                        </h4>
                        <textarea
                            value={editableThumbnailPrompt}
                            onChange={(e) => setEditableThumbnailPrompt(e.target.value)}
                            className="w-full p-3 bg-slate-900/70 rounded-md border border-slate-600 text-slate-300 text-sm italic min-h-[100px] focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                            placeholder="Edit prompt thumbnail di sini..."
                        />
                        <button onClick={handleGenerateThumbnail} disabled={isGeneratingThumbnail} className="w-full text-sm py-2 px-4 rounded-md font-semibold text-white bg-blue-600 hover:bg-blue-700 disabled:bg-slate-600 transition-colors shadow-lg">
                            {isGeneratingThumbnail ? 'Membuat Thumbnail...' : 'Hasilkan Thumbnail'}
                        </button>
                        <div className="mt-2 aspect-video bg-slate-900 rounded-md flex items-center justify-center border border-slate-700 relative overflow-hidden group">
                            {isGeneratingThumbnail && <div className="w-8 h-8 border-2 border-blue-400 border-t-transparent rounded-full animate-spin"></div>}
                            {thumbnailError && <p className="text-xs text-red-400 p-2">{thumbnailError}</p>}
                            {thumbnailImage && (
                            <>
                                <img src={thumbnailImage} alt="Generated Thumbnail" className="w-full h-full object-cover transition-transform group-hover:scale-105"/>
                                <a
                                    href={thumbnailImage}
                                    download={`thumbnail_${selectedIdea.title.replace(/\s+/g, '_')}.jpg`}
                                    className="absolute top-2 right-2 p-2 bg-slate-900/60 rounded-full text-white hover:bg-slate-700/80 transition-colors"
                                    aria-label="Unduh thumbnail"
                                    title="Unduh thumbnail"
                                >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                                </svg>
                                </a>
                            </>
                            )}
                            {!isGeneratingThumbnail && !thumbnailImage && !thumbnailError && <p className="text-slate-500 text-sm">Pratinjau Thumbnail</p>}
                        </div>
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* GLOBAL VOICE AND STYLE SETTINGS */}
      <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700 mb-8 sticky top-4 z-10 backdrop-blur-sm shadow-lg animate-fade-in">
          <h4 className="text-md font-bold text-slate-100 mb-3 text-center">Pengaturan Global Narasi</h4>
          <div className="max-w-md mx-auto">
              <div className="space-y-2">
                  <label htmlFor="global-voice" className="block text-xs font-medium text-slate-400 mb-1">Suara Narator</label>
                  <select
                      id="global-voice"
                      value={globalVoice}
                      onChange={e => setGlobalVoice(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-700 border border-slate-600 rounded-md text-slate-100 focus:ring-blue-500 focus:border-blue-500"
                  >
                      {voiceOptions.map(opt => (
                      <option key={opt.name} value={opt.value}>{opt.name}</option>
                      ))}
                  </select>
                  <label htmlFor="global-style" className="block text-xs font-medium text-slate-400 mb-1 mt-2">Gaya Bicara <span className="text-slate-500 text-xs">(contoh: ceria, misterius, lembut)</span></label>
                  <input
                      type="text"
                      id="global-style"
                      value={globalStyle}
                      onChange={e => setGlobalStyle(e.target.value)}
                      placeholder="Opsional: sesuaikan nada suara"
                      className="w-full text-sm p-2 bg-slate-700 border border-slate-600 rounded-md text-slate-100 placeholder-slate-500 focus:ring-blue-500 focus:border-blue-500"
                      />
              </div>
          </div>
      </div>


      {!script && !isLoadingScript && (
        <div className="bg-slate-800 p-6 rounded-lg border border-slate-700 animate-fade-in shadow-xl">
          <h3 className="text-xl font-bold text-slate-100 mb-4">Buat Naskah Lengkap</h3>
          <form onSubmit={handleGenerateScript} className="space-y-4">
            <div>
              <label htmlFor="duration" className="block text-sm font-medium text-slate-300 mb-2">
                Target Durasi Video (menit)
              </label>
              <select
                id="duration"
                value={duration}
                onChange={(e) => setDuration(e.target.value)}
                className="w-full px-4 py-3 bg-slate-700 border border-slate-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 transition duration-150 ease-in-out text-slate-100"
              >
                <option value="1">1 menit (Shorts/Reels)</option>
                <option value="5">5 menit</option>
                <option value="10">10 menit</option>
                <option value="15">15 menit</option>
                <option value="20">20 menit</option>
                <option value="30">30 menit</option>
              </select>
            </div>
            <button
              type="submit"
              className="w-full flex justify-center items-center py-3 px-4 border border-transparent rounded-md shadow-sm text-lg font-medium text-white bg-purple-600 hover:bg-purple-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 focus:ring-purple-500 disabled:bg-slate-600 disabled:cursor-not-allowed transition-colors duration-200"
            >
              Buat Naskah Video
            </button>
          </form>
        </div>
      )}

      {isLoadingScript && <LoadingSpinner />}
      {scriptError && <ErrorMessage message={scriptError} />}

      {script && (
        <div>
          <h3 className="text-3xl font-bold text-center mb-2 bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-blue-500">Naskah Video Lengkap</h3>
          <p className="text-center text-slate-400 mb-8">Setiap adegan siap untuk produksi. Hasilkan gambar dan audio di bawah.</p>

          <div className="space-y-8">
            {script.map((scene, index) => (
              <SceneCard 
                key={scene.scene_number} 
                scene={scene} 
                index={index} 
                voice={globalVoice}
                style={globalStyle}
                nicheId={selectedNiche.id}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

