const getLanguageName = (code: Language): string => {
    switch (code) {
        case 'en': return 'English';
        case 'ms': return 'Bahasa Melayu';
        case 'id':
        default: return 'Bahasa Indonesia';
    }
};

export const generateContentIdeas = async (theme: string, nicheId: string, language: Language = 'id'): Promise<Idea[]> => {
  if (!process.env.API_KEY) {
      throw new Error("API Key belum terdeteksi. Silakan hubungkan API Key Anda.");
  }
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const config = getNicheConfig(nicheId).idea;
  const langName = getLanguageName(language);

  const rules = config.aturan.replace(/Bahasa Indonesia/gi, langName);

  const prompt = `
    PERAN:
    ${config.persona}

    TUGAS:
    Hasilkan 3 ide konten video storytelling yang unik, menarik, dan SANGAT SPESIFIK berdasarkan tema yang saya berikan, sesuai dengan niche yang dipilih.

    TEMA UTAMA (FOKUS DI SINI):
    "${theme}"

    BAHASA OUTPUT:
    ${langName} (Pastikan judul, angle, dan hook menggunakan ${langName} yang baik dan benar).

    ATURAN:
    ${rules}
    6. Bahasa: Gunakan ${langName} yang baik dan benar.

    FORMAT OUTPUT:
    Berikan jawaban HANYA dalam format JSON yang sesuai dengan skema yang diberikan. Jangan tambahkan teks atau penjelasan lain di luar format JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: ideaSchema,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    const jsonText = response.text.trim();
    const parsedResponse = JSON.parse(jsonText);
    return parsedResponse.ideas;
  } catch (error) {
    console.error("Gemini API call failed:", error);
    throw new Error("Gagal menghasilkan ide dari Gemini.");
  }
};

const getSceneCountRange = (duration: string): string => {
    const minutes = parseInt(duration, 10);
    if (minutes === 1) return "2 sampai 3 adegan";
    if (minutes <= 5) return "4 sampai 6 adegan";
    if (minutes <= 10) return "8 sampai 12 adegan";
    if (minutes <= 15) return "13 sampai 17 adegan";
    if (minutes <= 20) return "18 sampai 22 adegan";
    return "25 sampai 30 adegan";
};

export const generateScript = async (idea: Idea, duration: string, nicheId: string, language: Language = 'id'): Promise<Scene[]> => {
  if (!process.env.API_KEY) {
      throw new Error("API Key belum terdeteksi. Silakan hubungkan API Key Anda.");
  }
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const sceneRange = getSceneCountRange(duration);
  const config = getNicheConfig(nicheId).script;
  const langName = getLanguageName(language);
  const rules = config.aturan.replace(/Bahasa Indonesia/gi, langName);

  const prompt = `
    PERAN:
    ${config.persona}

    TUGAS:
    Buatkan saya naskah storytelling lengkap berdasarkan ide video yang saya pilih, dengan target durasi tertentu, dan sesuai dengan gaya niche yang ditentukan.

    INPUT:
    - Ide Video: "${idea.title} - ${idea.angle}"
    - Target Durasi: "${duration}"

    BAHASA OUTPUT UNTUK NARASI (VOICE OVER):
    ${langName} (Sangat Penting). Judul adegan boleh menyesuaikan, tapi narasi harus full ${langName}.

    ATURAN KETAT:
    ${rules}
    4. Jumlah Adegan: Hasilkan jumlah adegan yang sesuai untuk video berdurasi ${duration}. Secara spesifik, buat antara ${sceneRange}.
    5. Bahasa Narasi: Gunakan ${langName}.

    FORMAT OUTPUT (PALING PENTING):
    Kembalikan jawaban HANYA dalam format JSON array yang valid. Jangan ada teks pembuka atau penutup di luar JSON.
  `;
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: scriptSchema,
        temperature: 0.7,
      },
    });

    const jsonText = response.text.trim();
    return JSON.parse(jsonText);
  } catch (error) {
    console.error("Gemini script generation failed:", error);
    throw new Error("Gagal membuat naskah.");
  }
};

export const generatePreProductionAssets = async (idea: Idea, nicheId: string, language: Language = 'id'): Promise<PreProductionAssets> => {
    if (!process.env.API_KEY) {
        throw new Error("API Key belum terdeteksi. Silakan hubungkan API Key Anda.");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const config = getNicheConfig(nicheId).assets;
    const langName = getLanguageName(language);
    const rules = config.aturan.replace(/Bahasa Indonesia/gi, langName);

    const prompt = `
        PERAN:
        ${config.persona}

        TUGAS:
        Berdasarkan ide video yang diberikan, hasilkan aset pra-produksi YouTube lengkap: 3 alternatif judul, satu prompt thumbnail yang sangat detail, satu teks thumbnail pendek, deskripsi video SEO-friendly, dan daftar hashtag populer.

        IDE VIDEO:
        - Judul Asli: "${idea.title}"
        - Deskripsi: "${idea.angle}"

        BAHASA OUTPUT:
        ${langName}. (Semua teks harus dalam ${langName}).

        ATURAN KETAT:
        ${rules}

        FORMAT OUTPUT:
        Hanya JSON yang valid sesuai skema yang diberikan. Jangan ada teks lain.
    `;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: preProductionAssetsSchema,
                temperature: 0.9,
            },
        });
        const jsonText = response.text.trim();
        return JSON.parse(jsonText);
    } catch (error) {
        console.error("Gemini pre-production assets generation failed:", error);
        throw new Error("Gagal membuat aset pra-produksi.");
    }
};

export const generateImageForScene = async (prompt: string): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API Key belum terdeteksi. Silakan hubungkan API Key Anda.");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: prompt }],
            },
        });

        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
                return part.inlineData.data; 
            }
        }
        throw new Error("API tidak mengembalikan gambar.");
    } catch (error) {
        console.error("Gemini image generation failed:", error);
        throw new Error("Gagal menghasilkan gambar.");
    }
};

export const generateAudioForScene = async (script: string, voiceName: string, style: string): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API Key belum terdeteksi. Silakan hubungkan API Key Anda.");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Say in a ${style || 'neutral'} tone: ${script}`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: prompt }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: voiceName },
                    },
                },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
            return base64Audio;
        } else {
             throw new Error("API tidak mengembalikan data audio.");
        }
    } catch (error) {
        console.error("Gemini audio generation failed:", error);
        throw new Error("Gagal menghasilkan audio.");
    }
};

