                        {thumbnailError && <p className="text-xs text-red-400 p-2 text-center">{thumbnailError}</p>}
                        {thumbnailImage && (
                          <>
                            <img src={thumbnailImage} alt="Thumbnail" className="w-full h-full object-cover"/>
