export const generateImageForScene = async (prompt: string): Promise<string> => {
    if (!process.env.API_KEY) throw new Error("API Key tidak ada.");
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: `Cinematic, high quality, detailed. ${prompt}` }],
            },
            config: {
                imageConfig: { aspectRatio: "16:9" }
            }
        });

        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) return part.inlineData.data; 
        }
        throw new Error("No image data.");
    } catch (error) {
        throw new Error("Gagal menghasilkan gambar.");
    }
};

export const generateAudioForScene = async (script: string, voiceName: string, style: string): Promise<string> => {
    if (!process.env.API_KEY) throw new Error("API Key tidak ada.");
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Say in a ${style || 'natural'} tone: ${script}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceName } },
                },
            },
        });
        return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
    } catch (error) {
        throw new Error("Gagal menghasilkan audio.");
    }
};

