                  <label className="block text-xs font-medium text-slate-400 mb-1">Gaya Bicara</label>
                  <input type="text" value={globalStyle} onChange={e => setGlobalStyle(e.target.value)} placeholder="Contoh: ceria, misterius" className="w-full text-sm p-2 bg-slate-700 border border-slate-600 rounded-md text-slate-100" />
              </div>
          </div>
      </div>

      {!script && !isLoadingScript && (
        <div className="bg-slate-800 p-6 rounded-lg border border-slate-700 shadow-xl">
