const getLanguageName = (code: Language): string => {
    switch (code) {
        case 'en': return 'English';
        case 'ms': return 'Bahasa Melayu';
        case 'id':
        default: return 'Bahasa Indonesia';
    }
};

const getSceneCountRange = (duration: string): string => {
    const minutes = parseInt(duration, 10);
    if (minutes === 1) return "Tepat 5 adegan";
    if (minutes === 5) return "Tepat 10 adegan";
    if (minutes === 10) return "Tepat 20 adegan";
    if (minutes === 15) return "Tepat 30 adegan";
    if (minutes === 20) return "Tepat 40 adegan";
    if (minutes === 30) return "Tepat 60 adegan";
    return `${minutes * 2} adegan`;
};

export const generateContentIdeas = async (theme: string, nicheId: string, language: Language = 'id'): Promise<Idea[]> => {
  if (!process.env.API_KEY) {
      throw new Error("API Key belum terdeteksi.");
  }
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const config = getNicheConfig(nicheId).idea;
  const langName = getLanguageName(language);
  const rules = config.aturan.replace(/Bahasa Indonesia/gi, langName);

  const prompt = `
    PERAN:
    ${config.persona}
    TUGAS:
    Hasilkan 3 ide konten video storytelling yang unik dan SPESIFIK berdasarkan tema: "${theme}".
    BAHASA: ${langName}.
    ATURAN: ${rules}
    FORMAT: JSON HANYA (skema ideaSchema).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: ideaSchema,
        temperature: 0.8,
      },
    });
    return JSON.parse(response.text.trim()).ideas;
  } catch (error) {
    throw new Error("Gagal menghasilkan ide.");
  }
};

export const generateScript = async (idea: Idea, duration: string, nicheId: string, language: Language = 'id'): Promise<Scene[]> => {
  if (!process.env.API_KEY) throw new Error("API Key tidak ada.");
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const config = getNicheConfig(nicheId).script;
  const langName = getLanguageName(language);
  const sceneCountLabel = getSceneCountRange(duration);

  const prompt = `
    PERAN: ${config.persona}
