export const generateImageForScene = async (prompt: string, referenceImage?: string): Promise<string> => {
  const parts: any[] = [{ text: prompt }];

  if (referenceImage) {
    const base64Data = referenceImage.split(',')[1];
    parts.push({
      inlineData: {
        data: base64Data,
        mimeType: 'image/jpeg'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts },
    config: {
      imageConfig: {
        aspectRatio: "16:9"
      }
    }
  });

  let base64 = "";
  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      base64 = part.inlineData.data;
    }
  }

  if (!base64) throw new Error("Gagal menghasilkan gambar dari model.");
  return base64;
};

export const generateAudioForScene = async (text: string, voiceName: string, style: string): Promise<string> => {
  const prompt = `Ucapkan kalimat berikut dengan gaya ${style}: ${text}`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: prompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Gagal menghasilkan audio dari model.");
  return base64Audio;
};

