const getTargetSceneCount = (duration: string): number => {
    const d = parseInt(duration);
    if (d === 1) return 4;
    if (d === 5) return 8;
    if (d === 10) return 15;
    if (d === 15) return 23;
    if (d === 20) return 30;
    if (d === 30) return 45;
    return 15; // default
};

export const generateContentIdeas = async (theme: string, nicheId: string, language: Language): Promise<Idea[]> => {
