  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Tema: "${theme}". Niche: "${nicheId}". Bahasa: ${langNames[language]}.
    ${config.idea.persona}
    Aturan: ${config.idea.aturan}`,
    config: {
