                           <button onClick={() => handleCopyText(assets.hashtags.join(' '), 'tag')} className="text-xs bg-slate-700 hover:bg-slate-600 text-slate-300 px-2 py-1 rounded transition-colors">
                             {copiedHashtags ? 'Tersalin!' : 'Salin'}
                           </button>
